pub fn validate_meteora_damm_v2_semantic_accounts<'info>(
    step_accounts: &[AccountInfo<'info>],
    direction: u8,
    input_mint: &AccountInfo<'info>,
    output_mint: &AccountInfo<'info>,
) -> Result<()> {
    require!(
        step_accounts.len() >= 8,
        ArbitrageError::InvalidAccountCount
    );
    require_keys_eq!(
        step_accounts[2].owner.key(),
        step_accounts[0].key(),
        ArbitrageError::InvalidAccount
    );

    let data = step_accounts[2].try_borrow_data()?;
    let pool = read_meteora_damm_v2_pool_semantic_keys(&data)?;
    require_keys_eq!(
        pool.token_a_mint,
        step_accounts[5].key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.token_b_mint,
        step_accounts[6].key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.token_a_vault,
        step_accounts[3].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.token_b_vault,
        step_accounts[4].key(),
        ArbitrageError::InvalidAccount
    );

    let (expected_input_mint, expected_output_mint) = match direction {
        0 => (pool.token_a_mint, pool.token_b_mint),
        1 => (pool.token_b_mint, pool.token_a_mint),
        _ => return Err(ArbitrageError::InvalidInstructionData.into()),
    };
    require_keys_eq!(
        expected_input_mint,
        input_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        expected_output_mint,
        output_mint.key(),
        ArbitrageError::InvalidTokenMint
    );

    validate_meteora_damm_v2_derived_accounts(step_accounts)
}

pub fn validate_meteora_dbc_semantic_accounts<'info>(
    step_accounts: &[AccountInfo<'info>],
    direction: u8,
    input_mint: &AccountInfo<'info>,
    output_mint: &AccountInfo<'info>,
) -> Result<()> {
    require!(
        step_accounts.len() >= 7,
        ArbitrageError::InvalidAccountCount
    );
    require_keys_eq!(
        step_accounts[2].owner.key(),
        step_accounts[0].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[3].owner.key(),
        step_accounts[0].key(),
        ArbitrageError::InvalidAccount
    );

    let pool_data = step_accounts[3].try_borrow_data()?;
    let pool = read_meteora_dbc_pool_semantic_keys(&pool_data)?;
    let config_data = step_accounts[2].try_borrow_data()?;
    let config = read_meteora_dbc_config_semantic_keys(&config_data)?;

    require_keys_eq!(
        pool.config,
        step_accounts[2].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.base_vault,
        step_accounts[4].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.quote_vault,
        step_accounts[5].key(),
        ArbitrageError::InvalidAccount
    );

    let (expected_input_mint, expected_output_mint) = match direction {
        0 => (pool.base_mint, config.quote_mint),
        1 => (config.quote_mint, pool.base_mint),
        _ => return Err(ArbitrageError::InvalidInstructionData.into()),
    };
    require_keys_eq!(
        expected_input_mint,
        input_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        expected_output_mint,
        output_mint.key(),
        ArbitrageError::InvalidTokenMint
    );

    validate_meteora_dbc_derived_accounts(step_accounts)
}

pub fn validate_meteora_dlmm_semantic_accounts<'info>(
    step_accounts: &[AccountInfo<'info>],
    direction: u8,
    input_mint: &AccountInfo<'info>,
    output_mint: &AccountInfo<'info>,
) -> Result<()> {
    require!(
        step_accounts.len() >= 13,
        ArbitrageError::InvalidAccountCount
    );
    require_keys_eq!(
        step_accounts[4].owner.key(),
        step_accounts[0].key(),
        ArbitrageError::InvalidAccount
    );

    let data = step_accounts[4].try_borrow_data()?;
    let pool = read_meteora_dlmm_pool_semantic_keys(&data)?;
    require_keys_eq!(
        pool.token_x_mint,
        step_accounts[7].key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.token_y_mint,
        step_accounts[8].key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.oracle,
        step_accounts[9].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[7].owner.key(),
        step_accounts[1].key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        step_accounts[8].owner.key(),
        step_accounts[2].key(),
        ArbitrageError::InvalidTokenMint
    );

    let (
        expected_input_mint,
        expected_output_mint,
        expected_input_reserve,
        expected_output_reserve,
    ) = match direction {
        0 => (
            pool.token_x_mint,
            pool.token_y_mint,
            pool.reserve_x,
            pool.reserve_y,
        ),
        1 => (
            pool.token_y_mint,
            pool.token_x_mint,
            pool.reserve_y,
            pool.reserve_x,
        ),
        _ => return Err(ArbitrageError::InvalidInstructionData.into()),
    };
    require_keys_eq!(
        expected_input_mint,
        input_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        expected_output_mint,
        output_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        expected_input_reserve,
        step_accounts[5].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        expected_output_reserve,
        step_accounts[6].key(),
        ArbitrageError::InvalidAccount
    );

    validate_meteora_dlmm_derived_accounts(step_accounts)
}

pub fn validate_meteora_damm_v1_semantic_accounts<'info>(
    step_accounts: &[AccountInfo<'info>],
    direction: u8,
    input_mint: &AccountInfo<'info>,
    output_mint: &AccountInfo<'info>,
) -> Result<()> {
    require!(
        step_accounts.len() >= 13,
        ArbitrageError::InvalidAccountCount
    );
    require_keys_eq!(
        step_accounts[1].owner.key(),
        step_accounts[0].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[2].owner.key(),
        step_accounts[12].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[3].owner.key(),
        step_accounts[12].key(),
        ArbitrageError::InvalidAccount
    );

    let pool_data = step_accounts[1].try_borrow_data()?;
    let pool = read_meteora_damm_v1_pool_semantic_keys(&pool_data)?;
    require_keys_eq!(
        pool.a_vault,
        step_accounts[2].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.b_vault,
        step_accounts[3].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.a_vault_lp,
        step_accounts[8].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.b_vault_lp,
        step_accounts[9].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.protocol_token_a_fee,
        step_accounts[10].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.protocol_token_b_fee,
        step_accounts[11].key(),
        ArbitrageError::InvalidAccount
    );

    let (expected_input_mint, expected_output_mint) = match direction {
        0 => (pool.token_a_mint, pool.token_b_mint),
        1 => (pool.token_b_mint, pool.token_a_mint),
        _ => return Err(ArbitrageError::InvalidInstructionData.into()),
    };
    require_keys_eq!(
        expected_input_mint,
        input_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        expected_output_mint,
        output_mint.key(),
        ArbitrageError::InvalidTokenMint
    );

    let a_vault_data = step_accounts[2].try_borrow_data()?;
    let b_vault_data = step_accounts[3].try_borrow_data()?;
    let a_vault = read_meteora_damm_v1_vault_semantic_keys(&a_vault_data)?;
    let b_vault = read_meteora_damm_v1_vault_semantic_keys(&b_vault_data)?;
    require_keys_eq!(
        a_vault.token_vault,
        step_accounts[4].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        b_vault.token_vault,
        step_accounts[5].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        a_vault.lp_mint,
        step_accounts[6].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        b_vault.lp_mint,
        step_accounts[7].key(),
        ArbitrageError::InvalidAccount
    );
    Ok(())
}

pub fn validate_raydium_launchpad_semantic_accounts<'info>(
    step_accounts: &[AccountInfo<'info>],
    base_mint: &AccountInfo<'info>,
    quote_mint: &AccountInfo<'info>,
) -> Result<()> {
    require!(
        step_accounts.len() >= 8,
        ArbitrageError::InvalidAccountCount
    );
    let data = step_accounts[4].try_borrow_data()?;
    let pool = read_raydium_launchpad_pool_semantic_keys(&data)?;
    require_keys_eq!(
        pool.global_config,
        step_accounts[2].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.platform_config,
        step_accounts[3].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.base_mint,
        base_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.quote_mint,
        quote_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.base_vault,
        step_accounts[5].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.quote_vault,
        step_accounts[6].key(),
        ArbitrageError::InvalidAccount
    );
    Ok(())
}

pub fn validate_pumpfun_swap_semantic_accounts<'info>(
    program: &AccountInfo<'info>,
    payer: &AccountInfo<'info>,
    associated_token_program: &AccountInfo<'info>,
    base_mint: &AccountInfo<'info>,
    quote_mint: &AccountInfo<'info>,
    base_token_program: &AccountInfo<'info>,
    quote_token_program: &AccountInfo<'info>,
    step_accounts: &[AccountInfo<'info>],
    direction: u8,
) -> Result<()> {
    let expected_len = match direction {
        0 => 17,
        1 => 18,
        _ => return Err(ArbitrageError::InvalidInstructionData.into()),
    };
    require!(
        step_accounts.len() == expected_len,
        ArbitrageError::InvalidAccountCount
    );

    let data = step_accounts[6].try_borrow_data()?;
    require!(
        data.starts_with(PUMPFUN_SWAP_BONDING_CURVE_DISCRIMINATOR),
        ArbitrageError::InvalidAccount
    );
    let creator = read_pubkey_from_data(&data, PUMPFUN_SWAP_BONDING_CURVE_CREATOR_OFFSET)?;
    let expected_creator_vault = Pubkey::find_program_address(
        &[PUMPFUN_SWAP_CREATOR_VAULT_SEED, creator.as_ref()],
        program.key,
    )
    .0;
    require_keys_eq!(
        step_accounts[9].key(),
        expected_creator_vault,
        ArbitrageError::InvalidAccount
    );

    require_keys_eq!(
        step_accounts[7].key(),
        associated_token_address_with_program_id(
            step_accounts[6].key,
            base_mint.key,
            base_token_program.key,
            associated_token_program.key,
        ),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[8].key(),
        associated_token_address_with_program_id(
            step_accounts[6].key,
            quote_mint.key,
            quote_token_program.key,
            associated_token_program.key,
        ),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[3].key(),
        associated_token_address_with_program_id(
            step_accounts[2].key,
            quote_mint.key,
            quote_token_program.key,
            associated_token_program.key,
        ),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[5].key(),
        associated_token_address_with_program_id(
            step_accounts[4].key,
            quote_mint.key,
            quote_token_program.key,
            associated_token_program.key,
        ),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[10].key(),
        associated_token_address_with_program_id(
            &expected_creator_vault,
            quote_mint.key,
            quote_token_program.key,
            associated_token_program.key,
        ),
        ArbitrageError::InvalidAccount
    );

    let fee_config_index = expected_len - 2;
    let event_authority_index = expected_len - 3;
    let expected_sharing_config = Pubkey::find_program_address(
        &[PUMPFUN_SHARING_CONFIG_SEED, base_mint.key.as_ref()],
        step_accounts[fee_config_index + 1].key,
    )
    .0;
    require_keys_eq!(
        step_accounts[11].key(),
        expected_sharing_config,
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        step_accounts[event_authority_index].key(),
        PUMPFUN_SWAP_EVENT_AUTHORITY,
        ArbitrageError::InvalidAccount
    );

    if direction == 1 {
        validate_pumpfun_volume_accounts(program, payer, &step_accounts[12], &step_accounts[13])?;
        validate_associated_pumpfun_user_volume_account(
            associated_token_program,
            quote_mint,
            quote_token_program,
            &step_accounts[13],
            &step_accounts[14],
        )?;
    } else {
        validate_pumpfun_user_volume_account(program, payer, &step_accounts[12])?;
        validate_associated_pumpfun_user_volume_account(
            associated_token_program,
            quote_mint,
            quote_token_program,
            &step_accounts[12],
            &step_accounts[13],
        )?;
    }
    validate_pumpfun_fee_config_accounts(
        &step_accounts[fee_config_index],
        &step_accounts[fee_config_index + 1],
        PUMPFUN_SWAP_FEE_CONFIG,
    )
}

pub fn validate_pumpfun_amm_semantic_accounts<'info>(
    program: &AccountInfo<'info>,
    payer: &AccountInfo<'info>,
    associated_token_program: &AccountInfo<'info>,
    quote_token_program: &AccountInfo<'info>,
    base_mint: &AccountInfo<'info>,
    quote_mint: &AccountInfo<'info>,
    step_accounts: &[AccountInfo<'info>],
) -> Result<()> {
    require!(
        step_accounts.len() == 12 || step_accounts.len() == 14 || step_accounts.len() == 16,
        ArbitrageError::InvalidAccountCount
    );

    let data = step_accounts[1].try_borrow_data()?;
    let pool = read_pumpfun_amm_pool_semantic_keys(&data)?;
    require_keys_eq!(
        pool.base_mint,
        base_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.quote_mint,
        quote_mint.key(),
        ArbitrageError::InvalidTokenMint
    );
    require_keys_eq!(
        pool.pool_base_token_account,
        step_accounts[3].key(),
        ArbitrageError::InvalidAccount
    );
    require_keys_eq!(
        pool.pool_quote_token_account,
        step_accounts[4].key(),
        ArbitrageError::InvalidAccount
    );

    let expected_creator_vault_authority = Pubkey::find_program_address(
        &[PUMPFUN_AMM_CREATOR_VAULT_SEED, pool.coin_creator.as_ref()],
        program.key,
    )
    .0;
    require_keys_eq!(
        step_accounts[9].key(),
        expected_creator_vault_authority,
        ArbitrageError::InvalidAccount
    );

    let expected_creator_vault_ata = associated_token_address_with_program_id(
        &expected_creator_vault_authority,
        quote_mint.key,
        quote_token_program.key,
        associated_token_program.key,
    );
    require_keys_eq!(
        step_accounts[8].key(),
        expected_creator_vault_ata,
        ArbitrageError::InvalidAccount
    );

    let (fee_config_index, has_volume_accounts) =
        pumpfun_amm_dynamic_suffix_layout(step_accounts, 10)?;
    if has_volume_accounts {
        validate_pumpfun_volume_accounts(program, payer, &step_accounts[10], &step_accounts[11])?;
    }
    validate_pumpfun_fee_config_accounts(
        &step_accounts[fee_config_index],
        &step_accounts[fee_config_index + 1],
        PUMPFUN_AMM_FEE_CONFIG,
    )
}

fn pumpfun_amm_dynamic_suffix_layout<'info>(
    step_accounts: &[AccountInfo<'info>],
    suffix_start: usize,
) -> Result<(usize, bool)> {
    let tail_len = step_accounts
        .len()
        .checked_sub(suffix_start)
        .ok_or(ArbitrageError::InvalidAccountCount)?;
    match tail_len {
        2 => Ok((suffix_start, false)),
        4 => {
            let buyback_only_fee_program_index = suffix_start
                .checked_add(1)
                .ok_or(ArbitrageError::InvalidAccountCount)?;
            if step_accounts[buyback_only_fee_program_index].executable {
                Ok((suffix_start, false))
            } else {
                Ok((
                    suffix_start
                        .checked_add(2)
                        .ok_or(ArbitrageError::InvalidAccountCount)?,
                    true,
                ))
            }
        }
        6 => Ok((
            suffix_start
                .checked_add(2)
                .ok_or(ArbitrageError::InvalidAccountCount)?,
            true,
        )),
        _ => Err(ArbitrageError::InvalidAccountCount.into()),
    }
}

