    #[test]
    fn raydium_cpmm_semantic_validation_checks_pool_state_accounts() {
        let amm_config_key = Pubkey::new_unique();
        let token0_vault_key = Pubkey::new_unique();
        let token1_vault_key = Pubkey::new_unique();
        let token0_mint_key = Pubkey::new_unique();
        let token1_mint_key = Pubkey::new_unique();
        let token0_program_key = Pubkey::new_unique();
        let token1_program_key = Pubkey::new_unique();
        let observation_key = Pubkey::new_unique();

        let step_accounts = vec![
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                false,
                true,
                vec![],
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                amm_config_key,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                true,
                false,
                raydium_cpmm_pool_data(
                    amm_config_key,
                    token0_vault_key,
                    token1_vault_key,
                    token0_mint_key,
                    token1_mint_key,
                    token0_program_key,
                    token1_program_key,
                    observation_key,
                ),
            ),
            test_account_with_data(
                token0_vault_key,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                token1_vault_key,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                observation_key,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
        ];
        let token0_mint = test_account_with_data(
            token0_mint_key,
            token0_program_key,
            false,
            false,
            false,
            vec![],
        );
        let token1_mint = test_account_with_data(
            token1_mint_key,
            token1_program_key,
            false,
            false,
            false,
            vec![],
        );
        let token0_program = test_account_with_data(
            token0_program_key,
            token0_program_key,
            false,
            false,
            true,
            vec![],
        );
        let token1_program = test_account_with_data(
            token1_program_key,
            token1_program_key,
            false,
            false,
            true,
            vec![],
        );

        assert!(validate_raydium_cpmm_semantic_accounts(
            &step_accounts,
            0,
            &token0_mint,
            &token1_mint,
            &token0_program,
            &token1_program,
        )
        .is_ok());

        let mut reverse_step_accounts = step_accounts.clone();
        reverse_step_accounts[4] = step_accounts[5].clone();
        reverse_step_accounts[5] = step_accounts[4].clone();
        assert!(validate_raydium_cpmm_semantic_accounts(
            &reverse_step_accounts,
            1,
            &token1_mint,
            &token0_mint,
            &token1_program,
            &token0_program,
        )
        .is_ok());

        let mut wrong_observation = step_accounts.clone();
        wrong_observation[6] = test_account_with_data(
            Pubkey::new_unique(),
            Pubkey::new_unique(),
            false,
            true,
            false,
            vec![],
        );
        let err = validate_raydium_cpmm_semantic_accounts(
            &wrong_observation,
            0,
            &token0_mint,
            &token1_mint,
            &token0_program,
            &token1_program,
        )
        .unwrap_err();
        assert_eq!(err, ArbitrageError::InvalidAccount.into());

        let wrong_output_mint = test_account_with_data(
            Pubkey::new_unique(),
            token1_program_key,
            false,
            false,
            false,
            vec![],
        );
        let err = validate_raydium_cpmm_semantic_accounts(
            &step_accounts,
            0,
            &token0_mint,
            &wrong_output_mint,
            &token0_program,
            &token1_program,
        )
        .unwrap_err();
        assert_eq!(err, ArbitrageError::InvalidTokenMint.into());

        let wrong_input_program = test_account_with_data(
            Pubkey::new_unique(),
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let err = validate_raydium_cpmm_semantic_accounts(
            &step_accounts,
            0,
            &token0_mint,
            &token1_mint,
            &wrong_input_program,
            &token1_program,
        )
        .unwrap_err();
        assert_eq!(err, ArbitrageError::InvalidAccount.into());
    }

