            let mut pool_data = step_accounts[1].try_borrow_mut_data().unwrap();
            pool_data[MERCURIAL_STABLE_SWAP_TOKEN_COUNT_OFFSET
                ..MERCURIAL_STABLE_SWAP_TOKEN_COUNT_OFFSET + 4]
                .copy_from_slice(&3_u32.to_le_bytes());
