    #[test]
    fn pumpfun_swap_semantic_validation_checks_creator_volume_and_fee_config() {
        let payer_key = Pubkey::new_unique();
        let base_mint_key = Pubkey::new_unique();
        let quote_mint_key = Pubkey::new_unique();
        let base_token_program_key = Pubkey::new_unique();
        let quote_token_program_key = Pubkey::new_unique();
        let associated_token_program_key = Pubkey::new_unique();
        let creator = Pubkey::new_unique();
        let bonding_curve = Pubkey::new_unique();
        let fee_recipient = Pubkey::new_unique();
        let buyback_fee_recipient = Pubkey::new_unique();
        let creator_vault = Pubkey::find_program_address(
            &[PUMPFUN_SWAP_CREATOR_VAULT_SEED, creator.as_ref()],
            &PUMPFUN_SWAP_PROGRAM_ID,
        )
        .0;
        let associated_quote_fee_recipient = associated_token_address_with_program_id(
            &fee_recipient,
            &quote_mint_key,
            &quote_token_program_key,
            &associated_token_program_key,
        );
        let associated_quote_buyback_fee_recipient = associated_token_address_with_program_id(
            &buyback_fee_recipient,
            &quote_mint_key,
            &quote_token_program_key,
            &associated_token_program_key,
        );
        let associated_base_bonding_curve = associated_token_address_with_program_id(
            &bonding_curve,
            &base_mint_key,
            &base_token_program_key,
            &associated_token_program_key,
        );
        let associated_quote_bonding_curve = associated_token_address_with_program_id(
            &bonding_curve,
            &quote_mint_key,
            &quote_token_program_key,
            &associated_token_program_key,
        );
        let associated_creator_vault = associated_token_address_with_program_id(
            &creator_vault,
            &quote_mint_key,
            &quote_token_program_key,
            &associated_token_program_key,
        );
        let sharing_config = Pubkey::find_program_address(
            &[PUMPFUN_SHARING_CONFIG_SEED, base_mint_key.as_ref()],
            &PUMPFUN_SWAP_FEE_CONFIG_PROGRAM_ID,
        )
        .0;
        let global_volume = Pubkey::find_program_address(
            &[PUMPFUN_GLOBAL_VOLUME_ACCUMULATOR_SEED],
            &PUMPFUN_SWAP_PROGRAM_ID,
        )
        .0;
        let user_volume = Pubkey::find_program_address(
            &[PUMPFUN_USER_VOLUME_ACCUMULATOR_SEED, payer_key.as_ref()],
            &PUMPFUN_SWAP_PROGRAM_ID,
        )
        .0;
        let associated_user_volume = associated_token_address_with_program_id(
            &user_volume,
            &quote_mint_key,
            &quote_token_program_key,
            &associated_token_program_key,
        );

        let program = test_account_with_data(
            PUMPFUN_SWAP_PROGRAM_ID,
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let payer =
            test_account_with_data(payer_key, Pubkey::new_unique(), true, true, false, vec![]);
        let associated_token_program = test_account_with_data(
            associated_token_program_key,
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let base_mint = test_account_with_data(
            base_mint_key,
            base_token_program_key,
            false,
            false,
            false,
            vec![],
        );
        let quote_mint = test_account_with_data(
            quote_mint_key,
            quote_token_program_key,
            false,
            false,
            false,
            vec![],
        );
        let base_token_program = test_account_with_data(
            base_token_program_key,
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let quote_token_program = test_account_with_data(
            quote_token_program_key,
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let step_accounts = vec![
            program.clone(),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                fee_recipient,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                associated_quote_fee_recipient,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                buyback_fee_recipient,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                associated_quote_buyback_fee_recipient,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                bonding_curve,
                Pubkey::new_unique(),
                false,
                true,
                false,
                pumpfun_swap_bonding_curve_data(creator),
            ),
            test_account_with_data(
                associated_base_bonding_curve,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                associated_quote_bonding_curve,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                creator_vault,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                associated_creator_vault,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                sharing_config,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                global_volume,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                user_volume,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                associated_user_volume,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                PUMPFUN_SWAP_EVENT_AUTHORITY,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                PUMPFUN_SWAP_FEE_CONFIG,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                PUMPFUN_SWAP_FEE_CONFIG_PROGRAM_ID,
                Pubkey::new_unique(),
                false,
                false,
                true,
                vec![],
            ),
        ];

        assert!(validate_pumpfun_swap_semantic_accounts(
            &program,
            &payer,
            &associated_token_program,
            &base_mint,
            &quote_mint,
            &base_token_program,
            &quote_token_program,
            &step_accounts,
            1,
        )
        .is_ok());

        let mut wrong_user_volume = step_accounts.clone();
        wrong_user_volume[13] = test_account_with_data(
            Pubkey::new_unique(),
            Pubkey::new_unique(),
            false,
            true,
            false,
            vec![],
        );
        let err = validate_pumpfun_swap_semantic_accounts(
            &program,
            &payer,
            &associated_token_program,
            &base_mint,
            &quote_mint,
            &base_token_program,
            &quote_token_program,
            &wrong_user_volume,
            1,
        )
        .unwrap_err();
        assert_eq!(err, ArbitrageError::InvalidAccount.into());

        let mut wrong_event_authority = step_accounts.clone();
        wrong_event_authority[15] = test_account_with_data(
            Pubkey::new_unique(),
            Pubkey::new_unique(),
            false,
            false,
            false,
            vec![],
        );
        let err = validate_pumpfun_swap_semantic_accounts(
            &program,
            &payer,
            &associated_token_program,
            &base_mint,
            &quote_mint,
            &base_token_program,
            &quote_token_program,
            &wrong_event_authority,
            1,
        )
        .unwrap_err();
        assert_eq!(err, ArbitrageError::InvalidAccount.into());
    }

    #[test]
    fn pumpfun_amm_semantic_validation_checks_pool_state_and_pdas() {
        let payer_key = Pubkey::new_unique();
        let base_mint_key = Pubkey::new_unique();
        let quote_mint_key = Pubkey::new_unique();
        let base_vault_key = Pubkey::new_unique();
        let quote_vault_key = Pubkey::new_unique();
        let coin_creator = Pubkey::new_unique();
        let associated_token_program_key = Pubkey::new_unique();
        let quote_token_program_key = Pubkey::new_unique();
        let creator_vault_authority = Pubkey::find_program_address(
            &[PUMPFUN_AMM_CREATOR_VAULT_SEED, coin_creator.as_ref()],
            &PUMPFUN_AMM_PROGRAM_ID,
        )
        .0;
        let creator_vault_ata = associated_token_address_with_program_id(
            &creator_vault_authority,
            &quote_mint_key,
            &quote_token_program_key,
            &associated_token_program_key,
        );
        let global_volume = Pubkey::find_program_address(
            &[PUMPFUN_GLOBAL_VOLUME_ACCUMULATOR_SEED],
            &PUMPFUN_AMM_PROGRAM_ID,
        )
        .0;
        let user_volume = Pubkey::find_program_address(
            &[PUMPFUN_USER_VOLUME_ACCUMULATOR_SEED, payer_key.as_ref()],
            &PUMPFUN_AMM_PROGRAM_ID,
        )
        .0;

        let program = test_account_with_data(
            PUMPFUN_AMM_PROGRAM_ID,
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let payer =
            test_account_with_data(payer_key, Pubkey::new_unique(), true, true, false, vec![]);
        let associated_token_program = test_account_with_data(
            associated_token_program_key,
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let quote_token_program = test_account_with_data(
            quote_token_program_key,
            Pubkey::new_unique(),
            false,
            false,
            true,
            vec![],
        );
        let base_mint = test_account_with_data(
            base_mint_key,
            Pubkey::new_unique(),
            false,
            false,
            false,
            vec![],
        );
        let quote_mint = test_account_with_data(
            quote_mint_key,
            Pubkey::new_unique(),
            false,
            false,
            false,
            vec![],
        );
        let step_accounts = vec![
            program.clone(),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                true,
                false,
                pumpfun_amm_pool_data(
                    base_mint_key,
                    quote_mint_key,
                    base_vault_key,
                    quote_vault_key,
                    coin_creator,
                ),
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                base_vault_key,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                quote_vault_key,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                creator_vault_ata,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                creator_vault_authority,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                global_volume,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                user_volume,
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                PUMPFUN_AMM_FEE_CONFIG,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                PUMPFUN_SWAP_FEE_CONFIG_PROGRAM_ID,
                Pubkey::new_unique(),
                false,
                false,
                true,
                vec![],
            ),
        ];

        assert!(validate_pumpfun_amm_semantic_accounts(
            &program,
            &payer,
            &associated_token_program,
            &quote_token_program,
            &base_mint,
            &quote_mint,
            &step_accounts,
        )
        .is_ok());

        let mut buyback_only_step_accounts = step_accounts[..10].to_vec();
        buyback_only_step_accounts.extend([
            test_account_with_data(
                PUMPFUN_AMM_FEE_CONFIG,
                Pubkey::new_unique(),
                false,
                false,
                false,
                vec![],
            ),
            test_account_with_data(
                PUMPFUN_SWAP_FEE_CONFIG_PROGRAM_ID,
                Pubkey::new_unique(),
                false,
                false,
                true,
                vec![],
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
            test_account_with_data(
                Pubkey::new_unique(),
                Pubkey::new_unique(),
                false,
                true,
                false,
                vec![],
            ),
        ]);

        assert!(validate_pumpfun_amm_semantic_accounts(
            &program,
            &payer,
            &associated_token_program,
            &quote_token_program,
            &base_mint,
            &quote_mint,
            &buyback_only_step_accounts,
        )
        .is_ok());

        let mut wrong_pool_vault = step_accounts.clone();
        wrong_pool_vault[3] = test_account_with_data(
            Pubkey::new_unique(),
            Pubkey::new_unique(),
            false,
            true,
            false,
            vec![],
        );
        let err = validate_pumpfun_amm_semantic_accounts(
            &program,
            &payer,
            &associated_token_program,
            &quote_token_program,
            &base_mint,
            &quote_mint,
            &wrong_pool_vault,
        )
        .unwrap_err();
        assert_eq!(err, ArbitrageError::InvalidAccount.into());
    }

    #[test]
    fn raydium_pool_v4_authority_validation_rejects_wrong_authority() {
        let program_id = Pubkey::new_unique();
        let program = test_account_with_data(
            program_id,
            Pubkey::new_unique(),
            false,
            false,
            true,
            Vec::new(),
        );
        let pool_state = test_account_with_data(
            Pubkey::new_unique(),
            program_id,
            false,
            true,
            false,
            raydium_pool_v4_state_data(1),
        );
        let authority = test_account_with_data(
            Pubkey::new_unique(),
            Pubkey::new_unique(),
            false,
            false,
            false,
            Vec::new(),
        );

        let err =
            validate_raydium_pool_v4_authority(&program, &pool_state, &authority).unwrap_err();

        assert_eq!(err, ArbitrageError::InvalidAccount.into());
    }
